# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
from flask import Blueprint, abort, jsonify, render_template, request
from flask_login import current_user
from app.auth_middleware import require_auth

from app.extensions import auth_write_limit
from app.i18n import t
from app.models import Supplement
from app.services import supplement_cabinet
from app.services.validators import _to_float


bp = Blueprint("supplements", __name__)


@bp.route("/supplements")
@require_auth
def supplements_page():
    supps = Supplement.query.filter_by(user_id=current_user.id)\
        .order_by(Supplement.created_at.desc()).all()
    return render_template("manage_stack.html",
        username=current_user.username,
        profile_picture=current_user.avatar_src,
        supplements=supps,
        categories=SUPPLEMENT_CATEGORIES,
        statuses=SUPPLEMENT_STATUSES,
        icons=CATEGORY_ICONS)


@bp.route("/supplement/add", methods=["POST"])
@require_auth
@auth_write_limit
def supplement_add():
    data = request.get_json(silent=True) or {}
    name = (data.get("product_name") or "").strip()
    brand = (data.get("brand") or "").strip()
    if not name or not brand:
        return jsonify({"error": t("manage_stack.required")}), 400

    category = data.get("category", "Other")
    if category not in SUPPLEMENT_CATEGORIES:
        category = "Other"
    status = data.get("status", "Active")
    if status not in SUPPLEMENT_STATUSES:
        status = "Active"

    def parse_rating(val):
        if val is None or val == "" or val == 0:
            return None
        try:
            v = int(val)
            return v if 1 <= v <= 5 else None
        except (ValueError, TypeError):
            return None

    fields = dict(
        product_name=name, brand=brand,
        category=category, status=status,
        rating_effect=parse_rating(data.get("rating_effect")),
        rating_taste=parse_rating(data.get("rating_taste")),
        rating_digestion=parse_rating(data.get("rating_digestion")),
        rating_price=parse_rating(data.get("rating_price")),
        review_text=(data.get("review_text") or "").strip() or None,
        price_paid=_to_float(data["price_paid"], None) if data.get("price_paid") else None,
        is_public=data.get("is_public", True),
    )
    # NUTR-PR7: persistence + first-supplement bonus (owner-row lock BEFORE the
    # count), activity and quest live in the ONE cabinet boundary shared with
    # the native transport.
    supp, quest_result = supplement_cabinet.create_supplement(current_user.id, fields)

    response = {"message": t("route.supp_added"), "id": supp.id}
    if quest_result:
        response["quest_awarded"] = quest_result
    return jsonify(response)


@bp.route("/supplement/edit/<int:sid>", methods=["POST"])
@require_auth
@auth_write_limit
def supplement_edit(sid):
    Supplement.query.filter_by(id=sid, user_id=current_user.id).first_or_404()

    data = request.get_json(silent=True) or {}
    changes = {}

    if "product_name" in data:
        name = (data["product_name"] or "").strip()
        if name:
            changes["product_name"] = name
    if "brand" in data:
        brand = (data["brand"] or "").strip()
        if brand:
            changes["brand"] = brand
    if "category" in data and data["category"] in SUPPLEMENT_CATEGORIES:
        changes["category"] = data["category"]
    if "status" in data and data["status"] in SUPPLEMENT_STATUSES:
        changes["status"] = data["status"]

    def parse_rating(val):
        if val is None or val == "" or val == 0:
            return None
        try:
            v = int(val)
            return v if 1 <= v <= 5 else None
        except (ValueError, TypeError):
            return None

    for field in ["rating_effect", "rating_taste", "rating_digestion", "rating_price"]:
        if field in data:
            changes[field] = parse_rating(data[field])
    if "review_text" in data:
        changes["review_text"] = (data["review_text"] or "").strip() or None
    if "price_paid" in data:
        changes["price_paid"] = _to_float(data["price_paid"], None) if data["price_paid"] else None
    if "is_public" in data:
        changes["is_public"] = bool(data["is_public"])

    if supplement_cabinet.update_supplement(current_user.id, sid, changes) is None:
        abort(404)
    return jsonify({"message": t("route.supp.updated")})


@bp.route("/supplement/delete/<int:sid>", methods=["POST"])
@require_auth
@auth_write_limit
def supplement_delete(sid):
    Supplement.query.filter_by(id=sid, user_id=current_user.id).first_or_404()
    if not supplement_cabinet.delete_supplement(current_user.id, sid):
        abort(404)
    return jsonify({"message": t("route.supp_deleted")})


# The canonical vocabularies live with the ONE cabinet boundary (NUTR-PR7).
SUPPLEMENT_CATEGORIES = supplement_cabinet.SUPPLEMENT_CATEGORIES


SUPPLEMENT_STATUSES   = supplement_cabinet.SUPPLEMENT_STATUSES


CATEGORY_ICONS = {
    "Protein": "\U0001f964", "Amino Acid": "\U0001f4a7", "Pre-Workout": "⚡",
    "Vitamin/Health": "\U0001f48a", "Creatine": "\U0001f4aa", "Other": "\U0001f4e6",
}
